@extends('layouts.app') @section('title',$attempt->exam->title) @section('content')<div class="mb-5 flex items-center justify-between rounded-3xl bg-slate-900 p-5 text-white"><div><div class="text-xs font-bold uppercase text-indigo-300">{{$attempt->exam->title}}</div><h2 class="text-xl font-black">SOAL <span id="currentNo">1</span> / {{$attempt->exam->questions->count()}}</h2></div><div class="text-right"><div class="text-xs text-slate-400">Sisa waktu</div><div id="timer" class="text-2xl font-black">--:--</div></div></div><div class="grid gap-5 lg:grid-cols-[1fr_260px]"><div>@foreach($attempt->exam->questions as $i=>$q)<section class="question rounded-3xl bg-white p-6 shadow-sm {{$i?'hidden':''}}" data-index="{{$i}}" data-id="{{$q->id}}">@if($q->story)<div class="math-content mb-6 whitespace-pre-wrap rounded-2xl border border-indigo-100 bg-indigo-50 p-5 leading-7">{!! strip_tags($q->story,'<p><br><strong><em>') !!}</div>@endif<div class="math-content text-lg leading-8">{!! strip_tags($q->question,'<p><br><strong><em>') !!}</div>@if($q->instructions)<p class="mt-3 text-sm text-slate-500">{{$q->instructions}}</p>@endif @php $saved=$attempt->answers->firstWhere('question_id',$q->id)?->answer; $opts=$attempt->exam->randomize_options?$q->options->shuffle():$q->options; @endphp @if($q->type==='multiple_choice')<div class="mt-6 space-y-3">@foreach($opts as $o)<label class="flex cursor-pointer gap-3 rounded-2xl border p-4 hover:border-indigo-400"><input class="answer mt-1" type="radio" name="q{{$q->id}}" value="{{$o->option_label}}" @checked($saved===$o->option_label)><span><b>{{$o->option_label}}.</b> <span class="math-content">{{$o->option_text}}</span></span></label>@endforeach</div>@else<textarea class="answer mt-6 w-full rounded-2xl border-slate-200" rows="10" placeholder="Tulis jawaban Anda...">{{$saved}}</textarea>@endif<div class="mt-3 text-xs font-semibold text-emerald-600 save-status"></div></section>@endforeach<div class="mt-5 flex justify-between"><button id="prev" class="rounded-2xl border bg-white px-5 py-3 font-bold">← Sebelumnya</button><button id="next" class="rounded-2xl bg-indigo-600 px-5 py-3 font-bold text-white">Berikutnya →</button></div></div><aside class="h-fit rounded-3xl bg-white p-5 shadow-sm"><h3 class="font-black">Daftar Soal</h3><div class="mt-4 grid grid-cols-5 gap-2">@foreach($attempt->exam->questions as $i=>$q)<button class="nav h-10 rounded-xl bg-slate-100 font-bold" data-go="{{$i}}">{{$i+1}}</button>@endforeach</div><div class="mt-5 text-xs text-slate-500">Hijau: sudah dijawab · Ungu: aktif</div><form method="post" action="{{route('attempts.submit',$attempt)}}" class="mt-6" onsubmit="return confirm('Kirim semua jawaban?')">@csrf<button class="w-full rounded-2xl bg-emerald-600 px-4 py-3 font-black text-white">Kirim Jawaban</button></form></aside></div>@include('questions.math')
<script>document.addEventListener('DOMContentLoaded',()=>{let cur=0,sections=[...document.querySelectorAll('.question')],deadline={{$deadline->timestamp}}*1000,csrf='{{csrf_token()}}';function show(n){cur=Math.max(0,Math.min(n,sections.length-1));sections.forEach((s,i)=>s.classList.toggle('hidden',i!==cur));document.querySelector('#currentNo').textContent=cur+1;document.querySelectorAll('.nav').forEach((b,i)=>{b.classList.toggle('bg-indigo-600',i===cur);b.classList.toggle('text-white',i===cur)})}document.querySelector('#prev').onclick=()=>show(cur-1);document.querySelector('#next').onclick=()=>show(cur+1);document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>show(+b.dataset.go));let timers=new Map;document.querySelectorAll('.answer').forEach(el=>el.oninput=()=>{let s=el.closest('.question'),value=el.type==='radio'?el.value:el.value;clearTimeout(timers.get(s));timers.set(s,setTimeout(async()=>{let res=await fetch('{{route('attempts.autosave',$attempt)}}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({question_id:s.dataset.id,answer:value})});if(res.ok){s.querySelector('.save-status').textContent='Tersimpan otomatis';document.querySelectorAll('.nav')[s.dataset.index].classList.add('bg-emerald-100','text-emerald-800')}},500))});setInterval(()=>{let sec=Math.max(0,Math.floor((deadline-Date.now())/1000));document.querySelector('#timer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec===0)document.querySelector('form[action$="/submit"]').submit()},1000);show(0)})</script>@endsection
